(5209475, 758182, 92577, '<td valign="top">crab''s eye view. Old idea still looks fresh 7</td>', 'crab''s eye view. Old idea still looks fresh 7', '2009-01-21 12:37:00.000000', NULL, 1),
(5209484, 758303, 92577, '<td valign="top">more grisly than ansel :)</td>', 'more grisly than ansel :)', '2009-01-21 12:39:39.000000', NULL, 1),
(5209523, 756096, 99384, '<td valign="top">Gorgeous! Absolute perfection!</td>', 'Gorgeous! Absolute perfection!', '2009-01-21 12:56:02.000000', NULL, 1),
(5209555, 756344, 102513, '<td valign="top">Looks scary yet inviting at the same time!</td>', 'Looks scary yet inviting at the same time!', '2009-01-21 13:12:09.000000', NULL, 1),
(5209577, 757537, 102513, '<td valign="top">Wow is this Vermillion in Alberta??</td>', 'Wow is this Vermillion in Alberta??', '2009-01-21 13:21:56.000000', NULL, 1),
(5209580, 757737, 30861, '<td valign="top">Of all the images entered in this challenge, this is by FAR the purest expression of Zone System. The image could be used in a textbook to illustrate ZS principles. You also have EXCELLENT raking light, and consequently great richness of textural detail. The details visible through the window, in particular, are absolutely spot-on in showing the concept of bringing out information from the deep shadows. In other words, from a technical perspective you have absolutely nailed what Ansel was about.<br/> <br/>Aesthetically, the image is not so spot-on. It''s well-composed and well executed, but it doesn''t carry a lot of emotive power. Not every image has to BE emotive, of course, but still it''s a missing element. I would not expect this image to ribbon, but if it doesn''t do very well I''ll be quite disappointed.</td>', 'Of all the images entered in this challenge, this is by FAR the purest expression of Zone System. The image could be used in a textbook to illustrate ZS principles. You also have EXCELLENT raking light, and consequently great richness of textural detail. The details visible through the window, in particular, are absolutely spot-on in showing the concept of bringing out information from the deep shadows. In other words, from a technical perspective you have absolutely nailed what Ansel was about. Aesthetically, the image is not so spot-on. It''s well-composed and well executed, but it doesn''t carry a lot of emotive power. Not every image has to BE emotive, of course, but still it''s a missing element. I would not expect this image to ribbon, but if it doesn''t do very well I''ll be quite disappointed.', '2009-01-21 13:23:28.000000', NULL, 1),
(5209583, 758143, 102513, '<td valign="top">Great shot!!</td>', 'Great shot!!', '2009-01-21 13:24:27.000000', NULL, 1),
(5209590, 758272, 30861, '<td valign="top">This is exceptionally nice from a tonal perspective. It''s marred a little, technically, by the skyline haloing. Compositionally it''s pretty nice, but just a bit lacking in the sense of not having a more dominant subject. For me, it''s more a picture of the sky than it is of the desert, actually, because the sky dominates here. Still and all, a very nice offering.</td>', 'This is exceptionally nice from a tonal perspective. It''s marred a little, technically, by the skyline haloing. Compositionally it''s pretty nice, but just a bit lacking in the sense of not having a more dominant subject. For me, it''s more a picture of the sky than it is of the desert, actually, because the sky dominates here. Still and all, a very nice offering.', '2009-01-21 13:26:28.000000', NULL, 1),
(5209593, 757537, 30861, '<td valign="top">I''m really bothered by the fact that this image is leaning noticeably to the right. It could be significantly improved by squaring it up.</td>', 'I''m really bothered by the fact that this image is leaning noticeably to the right. It could be significantly improved by squaring it up.', '2009-01-21 13:27:41.000000', NULL, 1),
(5209596, 757212, 30861, '<td valign="top">Very nice zone system work, holding detail in the shadows and the bright areas both.</td>', 'Very nice zone system work, holding detail in the shadows and the bright areas both.', '2009-01-21 13:28:45.000000', NULL, 1),
(5209598, 757453, 54446, '<td valign="top">I looked at this image for a long time.  Must have been exciting to stand in what appears to be the same spot as Ansel''s "Winter Storm Clearing".  There''s a lot to like in this image.  I like the contrast and the zones.  Maybe too bright in the clouds, or maybe I''d like to see more detail in the clouds, but sometimes the clouds don''t cooperate.  There are some factors holding back the score on this image.  I have looked at it on two different computers/monitors.  Seems to be pixelation in a couple spots.  Not sure if you unintentionally lowered the JPG quality too much.  Some halos, too.  Could be a filter you applied.  Might be oversharpening artifacts.  Sure is a great scene, but it does not snap to clarity for me.</td>', 'I looked at this image for a long time.  Must have been exciting to stand in what appears to be the same spot as Ansel''s "Winter Storm Clearing".  There''s a lot to like in this image.  I like the contrast and the zones.  Maybe too bright in the clouds, or maybe I''d like to see more detail in the clouds, but sometimes the clouds don''t cooperate.  There are some factors holding back the score on this image.  I have looked at it on two different computers/monitors.  Seems to be pixelation in a couple spots.  Not sure if you unintentionally lowered the JPG quality too much.  Some halos, too.  Could be a filter you applied.  Might be oversharpening artifacts.  Sure is a great scene, but it does not snap to clarity for me.', '2009-01-21 13:29:58.000000', NULL, 1),
(5209673, 758330, 35994, '<td valign="top">For me there''s just a little too much black, I don''t really understand the black piece along the bottom, I would''ve rather had seen the rest of the tree silhouette if it were possible.</td>', 'For me there''s just a little too much black, I don''t really understand the black piece along the bottom, I would''ve rather had seen the rest of the tree silhouette if it were possible.', '2009-01-21 14:05:24.000000', NULL, 1),
(5209677, 757109, 79057, '<td valign="top">Nice shot but could have used some contrast in my opinion.</td>', 'Nice shot but could have used some contrast in my opinion.', '2009-01-21 14:07:48.000000', NULL, 1),
(5209682, 758278, 35994, '<td valign="top">IMO if you could''ve made a little more contrast it would''ve really made this pop. Nice composition.</td>', 'IMO if you could''ve made a little more contrast it would''ve really made this pop. Nice composition.', '2009-01-21 14:09:50.000000', NULL, 1),
(5209685, 757443, 35994, '<td valign="top">Really nice contrast, the clouds look awesome.</td>', 'Really nice contrast, the clouds look awesome.', '2009-01-21 14:10:35.000000', NULL, 1),
(5209719, 757599, 92864, '<td valign="top">One of my favorites. Good luck!</td>', 'One of my favorites. Good luck!', '2009-01-21 14:22:22.000000', NULL, 1),
(5209746, 758190, 86974, '<td valign="top">Of all the images this one is most deffenatly done in the Ansel style, maybe the tree should be a little lighter but still looks god.</td>', 'Of all the images this one is most deffenatly done in the Ansel style, maybe the tree should be a little lighter but still looks god.', '2009-01-21 14:32:58.000000', NULL, 1),
(5209752, 758229, 86974, '<td valign="top">Looks nice but to be in the Ansel style maybe you could have lightend up the flower to pull the focus more onto it.</td>', 'Looks nice but to be in the Ansel style maybe you could have lightend up the flower to pull the focus more onto it.', '2009-01-21 14:34:58.000000', NULL, 1),
(5209754, 758143, 86974, '<td valign="top">Nice clean lines good job!</td>', 'Nice clean lines good job!', '2009-01-21 14:35:26.000000', NULL, 1),
(5209771, 756931, 42013, '<td valign="top">I like all of the lines created with your composition--feels a bit heavy handed to me in the sky and the sharpening in the grasses. Overall a decent job.</td>', 'I like all of the lines created with your composition--feels a bit heavy handed to me in the sky and the sharpening in the grasses. Overall a decent job.', '2009-01-21 14:39:39.000000', NULL, 1),
(5209774, 757453, 86974, '<td valign="top">When you walk in the Masters foot steps how could you not get such a nice image.Next time maybe you could come up with something original in the styel of Ansel. I do like the image althought you can see the clouds are a planted image.</td>', 'When you walk in the Masters foot steps how could you not get such a nice image.Next time maybe you could come up with something original in the styel of Ansel. I do like the image althought you can see the clouds are a planted image.', '2009-01-21 14:40:43.000000', NULL, 1),
(5209777, 758135, 42013, '<td valign="top">This has the best AA feel to me of the bunch. Maybe it''s the sliver of moon which reminds me of his Half Dome shot. Dunno, it stands on its own merits. Nicely done--the only thing I could wish for is a wisp of cloud. Or maybe not...</td>', 'This has the best AA feel to me of the bunch. Maybe it''s the sliver of moon which reminds me of his Half Dome shot. Dunno, it stands on its own merits. Nicely done--the only thing I could wish for is a wisp of cloud. Or maybe not...', '2009-01-21 14:41:21.000000', NULL, 1),
(5209779, 758037, 42013, '<td valign="top">One of the best in the challenge. Stark and perfect.</td>', 'One of the best in the challenge. Stark and perfect.', '2009-01-21 14:41:38.000000', NULL, 1),
(5209781, 757537, 42013, '<td valign="top">Has a classic look, nice sky with the mountains providing the contrast. Good work!</td>', 'Has a classic look, nice sky with the mountains providing the contrast. Good work!', '2009-01-21 14:42:02.000000', NULL, 1),
(5209784, 758190, 42013, '<td valign="top">Great quality of light here-- Good foreground form and I can see for miles.</td>', 'Great quality of light here-- Good foreground form and I can see for miles.', '2009-01-21 14:42:28.000000', NULL, 1),
(5209785, 757676, 86974, '<td valign="top">Nice! I hate to rate something with a vote highter then my own iamge but hey I can admite when someone puts together a better image.</td>', 'Nice! I hate to rate something with a vote highter then my own iamge but hey I can admite when someone puts together a better image.', '2009-01-21 14:42:48.000000', NULL, 1),
(5209787, 757979, 42013, '<td valign="top">Yours is the best of the rose/wood motif. Great mid-tones in the rose. Composition may be a little static but the light is great!</td>', 'Yours is the best of the rose/wood motif. Great mid-tones in the rose. Composition may be a little static but the light is great!', '2009-01-21 14:43:18.000000', NULL, 1),
(5209788, 758306, 42013, '<td valign="top">Simple and good. Good luck!</td>', 'Simple and good. Good luck!', '2009-01-21 14:43:31.000000', NULL, 1),
(5209790, 757516, 86974, '<td valign="top">Are you kidding with this image come on!</td>', 'Are you kidding with this image come on!', '2009-01-21 14:44:35.000000', NULL, 1),
(5209791, 758143, 42013, '<td valign="top">So, you and the other ''guy'' went out to the same place??! Yours is fantastic in its own right. Lots of clouds to break up the dark sky.</td>', 'So, you and the other ''guy'' went out to the same place??! Yours is fantastic in its own right. Lots of clouds to break up the dark sky.', '2009-01-21 14:44:38.000000', NULL, 1),
(5209799, 758037, 86974, '<td valign="top">Nice try but one tree out of all of these should be the focal point to be in the Adams style nice image though.</td>', 'Nice try but one tree out of all of these should be the focal point to be in the Adams style nice image though.', '2009-01-21 14:45:43.000000', NULL, 1),
(5209862, 758319, 79057, '<td valign="top">Nice contrast between the black and whites.</td>', 'Nice contrast between the black and whites.', '2009-01-21 15:03:08.000000', NULL, 1),
(5209910, 757759, 79057, '<td valign="top">Very crisp ... I love the way the whites come out and the sharpness of the grass and cows.</td>', 'Very crisp ... I love the way the whites come out and the sharpness of the grass and cows.', '2009-01-21 15:16:16.000000', NULL, 1),
(5209921, 757354, 79057, '<td valign="top">I really like this composition but think more contrast in the sky would be my preference.</td>', 'I really like this composition but think more contrast in the sky would be my preference.', '2009-01-21 15:20:18.000000', NULL, 1),
(5209931, 758038, 79057, '<td valign="top">It''s a peaceful shot but I think inverting the lights with the darks would have worked better personally.</td>', 'It''s a peaceful shot but I think inverting the lights with the darks would have worked better personally.', '2009-01-21 15:24:18.000000', NULL, 1),
(5209937, 757912, 96751, '<td valign="top">Marvelous symmetry.  The upper half of the mountains on the right, however, are too dull and flat.</td>', 'Marvelous symmetry.  The upper half of the mountains on the right, however, are too dull and flat.', '2009-01-21 15:27:42.000000', NULL, 1),
(5209938, 757354, 96751, '<td valign="top">Very brooding.  Lighting in the sky is dramatic, but overall a bit flat and untextured.</td>', 'Very brooding.  Lighting in the sky is dramatic, but overall a bit flat and untextured.', '2009-01-21 15:28:23.000000', NULL, 1),
(5209940, 758296, 96751, '<td valign="top">Mice sense of motion in this.  Looks too over processed for Ansel.</td>', 'Mice sense of motion in this.  Looks too over processed for Ansel.', '2009-01-21 15:29:00.000000', NULL, 1),
(5209944, 757485, 96751, '<td valign="top">Love the shapes and composition of this shot, but doesn''t feel "Ansel-y".</td>', 'Love the shapes and composition of this shot, but doesn''t feel "Ansel-y".', '2009-01-21 15:30:17.000000', NULL, 1),
(5209947, 758037, 96751, '<td valign="top">What a fabulous painting-like quality.  Great geometry.  Not enough detail in the bark or ground for it to be truly Ansel.</td>', 'What a fabulous painting-like quality.  Great geometry.  Not enough detail in the bark or ground for it to be truly Ansel.', '2009-01-21 15:31:02.000000', NULL, 1),
(5209950, 758198, 96751, '<td valign="top">Though the sky is very dramatic, a tighter cropping to natural thirds would have greatly enhanced this shot.</td>', 'Though the sky is very dramatic, a tighter cropping to natural thirds would have greatly enhanced this shot.', '2009-01-21 15:32:02.000000', NULL, 1),
(5209953, 758242, 96751, '<td valign="top">One of several saguaro shots.  This one lacks a bit of drama and dynamics, and the isn''t enough differentiation between the ground and the distant mountains.</td>', 'One of several saguaro shots.  This one lacks a bit of drama and dynamics, and the isn''t enough differentiation between the ground and the distant mountains.', '2009-01-21 15:33:03.000000', NULL, 1),
(5209955, 758002, 96751, '<td valign="top">A similar view confirmed my non-meat-eating status over 30 years ago.</td>', 'A similar view confirmed my non-meat-eating status over 30 years ago.', '2009-01-21 15:33:58.000000', NULL, 1),
(5209957, 757294, 96751, '<td valign="top">This shot has some really good dimensions and depth, but overall it''s rather dark and dull.</td>', 'This shot has some really good dimensions and depth, but overall it''s rather dark and dull.', '2009-01-21 15:35:01.000000', NULL, 1),
(5209959, 758220, 79057, '<td valign="top">I like the composition but find the overexposed water part a bit distracting.</td>', 'I like the composition but find the overexposed water part a bit distracting.', '2009-01-21 15:35:31.000000', NULL, 1),
(5209960, 758069, 96751, '<td valign="top">Xmas card!</td>', 'Xmas card!', '2009-01-21 15:35:49.000000', NULL, 1),
(5209962, 757379, 96751, '<td valign="top">The foreground tree and base shadow are amazing.  The background tree not so much.</td>', 'The foreground tree and base shadow are amazing.  The background tree not so much.', '2009-01-21 15:36:36.000000', NULL, 1),
(5209968, 758135, 96751, '<td valign="top">Great capture of the moon, but I''m not crazy about the rocks - they look dull and flat.</td>', 'Great capture of the moon, but I''m not crazy about the rocks - they look dull and flat.', '2009-01-21 15:37:32.000000', NULL, 1),
(5209969, 757972, 96751, '<td valign="top">Nice yin/yang composition.  I''d have liked a little more light on the rocks, which are too dark globby looking.</td>', 'Nice yin/yang composition.  I''d have liked a little more light on the rocks, which are too dark globby looking.', '2009-01-21 15:38:14.000000', NULL, 1),
(5209973, 757516, 79057, '<td valign="top">Not sure if this new border style works for me.</td>', 'Not sure if this new border style works for me.', '2009-01-21 15:39:13.000000', NULL, 1),
(5209974, 756458, 96751, '<td valign="top">Holy Cow!!!  Who''d you pay off to get that sky!!!??  Incredible detail on the cactus, really pops from the background and gravel.  My first (and only) 10.</td>', 'Holy Cow!!!  Who''d you pay off to get that sky!!!??  Incredible detail on the cactus, really pops from the background and gravel.  My first (and only) 10.', '2009-01-21 15:39:25.000000', NULL, 1),
(5209975, 757328, 79057, '<td valign="top">Nice how contrasting the rock comes out.</td>', 'Nice how contrasting the rock comes out.', '2009-01-21 15:39:49.000000', NULL, 1),
(5209976, 758039, 79057, '<td valign="top">Impressive location and nice shot ... it does lacks some contrast in my opinion.</td>', 'Impressive location and nice shot ... it does lacks some contrast in my opinion.', '2009-01-21 15:41:11.000000', NULL, 1),
(5210197, 757145, 102513, '<td valign="top">Background is a bit too overexposed for my liking</td>', 'Background is a bit too overexposed for my liking', '2009-01-21 17:19:20.000000', NULL, 1),
(5210199, 757447, 99506, '<td valign="top">Great DOF with focus, distict zones of exposure I''d have to say meets the challenge perfectly good one</td>', 'Great DOF with focus, distict zones of exposure I''d have to say meets the challenge perfectly good one', '2009-01-21 17:20:30.000000', NULL, 1),
(5210203, 758280, 99506, '<td valign="top">Nice shot but for me the lack of DOF doesn''t shout Ansel Adams to me</td>', 'Nice shot but for me the lack of DOF doesn''t shout Ansel Adams to me', '2009-01-21 17:22:01.000000', NULL, 1),
(5210206, 757657, 99506, '<td valign="top">Nice DOF with distinct areas of differing exposure good one</td>', 'Nice DOF with distinct areas of differing exposure good one', '2009-01-21 17:23:18.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5210209, 757598, 99506, '<td valign="top">I like this shot but looks as if it was converted to B&amp;W using Hue and Saturation as it seesm to have a bit of a tint to it, but I''m no expert.</td>', 'I like this shot but looks as if it was converted to B&W using Hue and Saturation as it seesm to have a bit of a tint to it, but I''m no expert.', '2009-01-21 17:24:10.000000', NULL, 1),
(5210210, 757192, 99506, '<td valign="top">Great DOF, nice zones of exposure, fits the bill well.</td>', 'Great DOF, nice zones of exposure, fits the bill well.', '2009-01-21 17:24:44.000000', NULL, 1),
(5210219, 757117, 68987, '<td valign="top">Overexposed</td>', 'Overexposed', '2009-01-21 17:39:03.000000', NULL, 1),
(5210258, 757676, 102513, '<td valign="top">Great 3D quality to it!</td>', 'Great 3D quality to it!', '2009-01-21 18:11:09.000000', NULL, 1),
(5210295, 758216, 102426, '<td valign="top">the reflection is distracting</td>', 'the reflection is distracting', '2009-01-21 18:46:19.000000', NULL, 1),
(5210301, 757745, 102426, '<td valign="top">really cool. great contrast</td>', 'really cool. great contrast', '2009-01-21 18:48:57.000000', NULL, 1),
