(5212273, 758272, 101318, '<td valign="top">CLOUDS YES.</td>', 'CLOUDS YES.', '2009-01-22 17:13:07.000000', NULL, 1),
(5212275, 757971, 101318, '<td valign="top">Great rich contrasts in the Mountain and Sky</td>', 'Great rich contrasts in the Mountain and Sky', '2009-01-22 17:13:36.000000', NULL, 1),
(5212284, 757997, 101318, '<td valign="top">Nice long exposure. It could use a bit less "grey" and more blacks and whites</td>', 'Nice long exposure. It could use a bit less "grey" and more blacks and whites', '2009-01-22 17:16:14.000000', NULL, 1),
(5212294, 757453, 101318, '<td valign="top">WOW nice composition. Great looking clouds. Only markdown is because the mountains appear oversharpened</td>', 'WOW nice composition. Great looking clouds. Only markdown is because the mountains appear oversharpened', '2009-01-22 17:18:09.000000', NULL, 1),
(5212299, 757212, 101318, '<td valign="top">Nice framing. Good lighting and contrasts</td>', 'Nice framing. Good lighting and contrasts', '2009-01-22 17:18:53.000000', NULL, 1),
(5212306, 757421, 101318, '<td valign="top">Composition could work, but it needs more contrasts.</td>', 'Composition could work, but it needs more contrasts.', '2009-01-22 17:19:54.000000', NULL, 1),
(5212318, 758263, 101318, '<td valign="top">Awesome composition. The sky is perfect. The top of the cliff looks a bit too dark.</td>', 'Awesome composition. The sky is perfect. The top of the cliff looks a bit too dark.', '2009-01-22 17:23:31.000000', NULL, 1),
(5212350, 757930, 101318, '<td valign="top">Sky is great. The remaining picture appears a little soft</td>', 'Sky is great. The remaining picture appears a little soft', '2009-01-22 17:39:52.000000', NULL, 1),
(5212355, 756931, 101318, '<td valign="top">Good sky. It look slightly overprocessed</td>', 'Good sky. It look slightly overprocessed', '2009-01-22 17:41:37.000000', NULL, 1),
(5212363, 758093, 101702, '<td valign="top">Nice subject matter but overprocessed in my opinion.</td>', 'Nice subject matter but overprocessed in my opinion.', '2009-01-22 17:46:24.000000', NULL, 1),
(5212366, 758067, 101702, '<td valign="top">Would be a slightly better pic if the ground was level.</td>', 'Would be a slightly better pic if the ground was level.', '2009-01-22 17:47:04.000000', NULL, 1),
(5212377, 758296, 52130, '<td valign="top">weird pink tone</td>', 'weird pink tone', '2009-01-22 17:50:30.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5212378, 756468, 101318, '<td valign="top">This one has some potential. It just looks out of focus</td>', 'This one has some potential. It just looks out of focus', '2009-01-22 17:50:41.000000', NULL, 1),
(5212379, 757556, 101318, '<td valign="top">Funny DNMC</td>', 'Funny DNMC', '2009-01-22 17:51:29.000000', NULL, 1),
(5212380, 758280, 101318, '<td valign="top">Good composition. It needs much more DOF</td>', 'Good composition. It needs much more DOF', '2009-01-22 17:52:26.000000', NULL, 1),
(5212384, 757516, 52130, '<td valign="top">lol</td>', 'lol', '2009-01-22 17:53:04.000000', NULL, 1),
(5212387, 758267, 52130, '<td valign="top">great dark sky but not very sharp</td>', 'great dark sky but not very sharp', '2009-01-22 17:54:59.000000', NULL, 1),
(5212416, 756547, 48389, '<td valign="top">Have you tried to dodge and burn the tree in places? I can see what appears to be patches of lighter areas on the branches which don''t quite look right. Do like the composition and the sky is great.</td>', 'Have you tried to dodge and burn the tree in places? I can see what appears to be patches of lighter areas on the branches which don''t quite look right. Do like the composition and the sky is great.', '2009-01-22 18:18:53.000000', NULL, 1),
(5212444, 757452, 48389, '<td valign="top">Just down the road from me :o) Unfortunately this looks a like it needs to be straightened a bit and whilst I like the low perspective I think there are stronger compositions at this location. This is just MHO</td>', 'Just down the road from me :o) Unfortunately this looks a like it needs to be straightened a bit and whilst I like the low perspective I think there are stronger compositions at this location. This is just MHO', '2009-01-22 18:36:54.000000', NULL, 1),
(5212451, 757293, 101702, '<td valign="top">A lovely picture of a rose, but I can''t help think it would me more iconically Ansel if it had some driftwood too :-)<br/> <br/>I still predict this will score well though.</td>', 'A lovely picture of a rose, but I can''t help think it would me more iconically Ansel if it had some driftwood too :-) I still predict this will score well though.', '2009-01-22 18:42:24.000000', NULL, 1),
(5212461, 758263, 76598, '<td valign="top">This image is very well composed and has a great perspective, a beautiful image; BUT I have have problem with the processing.  With an image this compositionally strong and so much going for it, it strikes me that far to image management has been done to it.</td>', 'This image is very well composed and has a great perspective, a beautiful image; BUT I have have problem with the processing.  With an image this compositionally strong and so much going for it, it strikes me that far to image management has been done to it.', '2009-01-22 18:54:38.000000', NULL, 1),
(5212462, 757556, 76598, '<td valign="top">massive credit for the creative ABUSE of a good Adams image</td>', 'massive credit for the creative ABUSE of a good Adams image', '2009-01-22 18:55:52.000000', NULL, 1),
(5212464, 757501, 76598, '<td valign="top">I love the texture and contrast in this image, the crows are a great additional touch....but I really wish that tree wasn''t dead center</td>', 'I love the texture and contrast in this image, the crows are a great additional touch....but I really wish that tree wasn''t dead center', '2009-01-22 18:57:06.000000', NULL, 1),
(5212473, 758280, 45857, '<td valign="top">interesting picture.....read up on the f/64 group</td>', 'interesting picture.....read up on the f/64 group', '2009-01-22 19:05:11.000000', NULL, 1),
(5212477, 756622, 45857, '<td valign="top">good tonal range, good comp...not to hot on the border.</td>', 'good tonal range, good comp...not to hot on the border.', '2009-01-22 19:06:37.000000', NULL, 1),
(5212480, 758130, 45857, '<td valign="top">interesting details but some what hard to find the subject, nice B/W conversion.</td>', 'interesting details but some what hard to find the subject, nice B/W conversion.', '2009-01-22 19:08:10.000000', NULL, 1),
(5212481, 757816, 45857, '<td valign="top">Nice comp, read up on the f64 group</td>', 'Nice comp, read up on the f64 group', '2009-01-22 19:09:25.000000', NULL, 1),
(5212482, 757346, 45857, '<td valign="top">very Adamesque</td>', 'very Adamesque', '2009-01-22 19:09:57.000000', NULL, 1),
(5212489, 758300, 45857, '<td valign="top">Good comp, think Ansel would have wanted more in the background, but I like it</td>', 'Good comp, think Ansel would have wanted more in the background, but I like it', '2009-01-22 19:16:33.000000', NULL, 1),
(5212496, 757782, 45857, '<td valign="top">Pittsford , NY?<br/>I used to live there.......  here''s a 7<br/>(because it deserves it.)<br/>would have been better without the well beaten trail</td>', 'Pittsford , NY?I used to live there.......  here''s a 7(because it deserves it.)would have been better without the well beaten trail', '2009-01-22 19:19:43.000000', NULL, 1),
(5212502, 757745, 101702, '<td valign="top">Awesome! My pick for the blue</td>', 'Awesome! My pick for the blue', '2009-01-22 19:21:55.000000', NULL, 1),
(5212503, 756622, 101702, '<td valign="top">This is a great shot, but the border spoils it in my opinion. It''s still in my top 10 but I think it''ll just miss out on a ribbon. I think a solid border would have worked better.</td>', 'This is a great shot, but the border spoils it in my opinion. It''s still in my top 10 but I think it''ll just miss out on a ribbon. I think a solid border would have worked better.', '2009-01-22 19:22:03.000000', NULL, 1),
(5212504, 757334, 101702, '<td valign="top">One of the better rose and wood entries in the challenge.</td>', 'One of the better rose and wood entries in the challenge.', '2009-01-22 19:22:15.000000', NULL, 1),
(5212506, 758271, 45857, '<td valign="top">needs a little more tonal range, at least on my monitor, and would have like the comp a bit more to the right, cropped a bit closer to the right most tree.<br/>Great choice of subject ....</td>', 'needs a little more tonal range, at least on my monitor, and would have like the comp a bit more to the right, cropped a bit closer to the right most tree.Great choice of subject ....', '2009-01-22 19:22:42.000000', NULL, 1),
(5212512, 756350, 45857, '<td valign="top">good tonal range, could be a bit sharper<br/>What''s with the dots on the border?</td>', 'good tonal range, could be a bit sharperWhat''s with the dots on the border?', '2009-01-22 19:23:57.000000', NULL, 1),
(5212514, 757938, 45857, '<td valign="top">Tonal range a bit shallow, needs stronger blacks, but good subject.</td>', 'Tonal range a bit shallow, needs stronger blacks, but good subject.', '2009-01-22 19:25:19.000000', NULL, 1),
(5212515, 757212, 45857, '<td valign="top">Excellent job.....</td>', 'Excellent job.....', '2009-01-22 19:26:03.000000', NULL, 1),
(5212517, 757891, 35994, '<td valign="top">Awesome composition &amp; contrast. IMO the thick center line towards the top looks just a little tilted (a minor distraction). This is really neat, it was the first one in several that really caught my eye. I''ll be anxious to see how this does with the voters.</td>', 'Awesome composition & contrast. IMO the thick center line towards the top looks just a little tilted (a minor distraction). This is really neat, it was the first one in several that really caught my eye. I''ll be anxious to see how this does with the voters.', '2009-01-22 19:27:22.000000', NULL, 1),
(5212631, 757443, 54446, '<td valign="top">If AA had ever decided to place people in his landscape images, this is how he would have done it.  Amazing tones and great composition.  Your masterful processing and BW conversion of this image earns it my top score 10 and is my favorite in this challenge.  Beautiful and eye-pleasing image.</td>', 'If AA had ever decided to place people in his landscape images, this is how he would have done it.  Amazing tones and great composition.  Your masterful processing and BW conversion of this image earns it my top score 10 and is my favorite in this challenge.  Beautiful and eye-pleasing image.', '2009-01-22 19:56:03.000000', NULL, 1),
(5212634, 756930, 54446, '<td valign="top">You understand contrast, tones and lighting very well.  Your composition is outstanding.  9</td>', 'You understand contrast, tones and lighting very well.  Your composition is outstanding.  9', '2009-01-22 19:56:07.000000', NULL, 1),
(5212637, 758143, 54446, '<td valign="top">Excellent and interesting.  9</td>', 'Excellent and interesting.  9', '2009-01-22 19:56:14.000000', NULL, 1),
(5212638, 757676, 54446, '<td valign="top">Wow!  AA would like this very much.  Great job of enhancing details in the shadows.  Super control of highlights.  Great tonal range throughout.  9</td>', 'Wow!  AA would like this very much.  Great job of enhancing details in the shadows.  Super control of highlights.  Great tonal range throughout.  9', '2009-01-22 19:56:23.000000', NULL, 1),
(5212640, 757662, 54446, '<td valign="top">Outstanding tonal range.  Just the right detail in the shadow.  Superb clarity.  I like the toning very much.... maybe a selenium?  eta:  Interesting that on my home computer, I don''t see the toning I thought I saw at my work computer.  Looks great, regardless.  9</td>', 'Outstanding tonal range.  Just the right detail in the shadow.  Superb clarity.  I like the toning very much.... maybe a selenium?  eta:  Interesting that on my home computer, I don''t see the toning I thought I saw at my work computer.  Looks great, regardless.  9', '2009-01-22 19:56:31.000000', NULL, 1),
(5212778, 757676, 98171, '<td valign="top">The only image I gave a 10 in this challenge. Awesome perspective, just an overall amazing photo.</td>', 'The only image I gave a 10 in this challenge. Awesome perspective, just an overall amazing photo.', '2009-01-22 20:45:42.000000', NULL, 1),
(5212792, 758215, 98171, '<td valign="top">Great overall story here, the mood really works for me. I like your perspective. The contrast/lighting is perfect.</td>', 'Great overall story here, the mood really works for me. I like your perspective. The contrast/lighting is perfect.', '2009-01-22 20:50:06.000000', NULL, 1),
(5212805, 758196, 98171, '<td valign="top">While I give you credit for replicating his still life image, the challenge called for a photo "in the style of Ansel". I cannot think very highly of a "copycat" image, when there were so many other options for the challenge. Maybe if you had adjusted the darkness/contrast, the image would be a bit more powerful.</td>', 'While I give you credit for replicating his still life image, the challenge called for a photo "in the style of Ansel". I cannot think very highly of a "copycat" image, when there were so many other options for the challenge. Maybe if you had adjusted the darkness/contrast, the image would be a bit more powerful.', '2009-01-22 20:54:19.000000', NULL, 1),
(5212807, 758139, 98171, '<td valign="top">The composition of this photo is poor. To be blunt, there is nothing worth looking at. While you did play around with the contrast, and it helps the image  along, it just does not "work" for the challenge IMO.</td>', 'The composition of this photo is poor. To be blunt, there is nothing worth looking at. While you did play around with the contrast, and it helps the image  along, it just does not "work" for the challenge IMO.', '2009-01-22 20:56:10.000000', NULL, 1),
(5212810, 757516, 98171, '<td valign="top">Well, good joke I suppose. 1</td>', 'Well, good joke I suppose. 1', '2009-01-22 20:56:21.000000', NULL, 1),
(5212813, 757657, 98171, '<td valign="top">Your perspective makes it hard to look at the image; I cant decide where to look first, or what I am looking at.</td>', 'Your perspective makes it hard to look at the image; I cant decide where to look first, or what I am looking at.', '2009-01-22 20:57:01.000000', NULL, 1),
(5212815, 758029, 98171, '<td valign="top">I wish you had taken a different angle on this photo, to give it more interest, as well as not centering the tree.</td>', 'I wish you had taken a different angle on this photo, to give it more interest, as well as not centering the tree.', '2009-01-22 20:57:40.000000', NULL, 1),
(5212819, 758219, 108248, '<td valign="top">probably should have saved this for the single tree challenge, but still a decent photo</td>', 'probably should have saved this for the single tree challenge, but still a decent photo', '2009-01-22 20:59:08.000000', NULL, 1),
(5212824, 756878, 102889, '<td valign="top">For me... this is a 10, and in the true nature of this challenge.</td>', 'For me... this is a 10, and in the true nature of this challenge.', '2009-01-22 21:00:05.000000', NULL, 1),
(5212831, 756350, 98171, '<td valign="top">This picture just has very little visual interest. It doesn''t make me think "Ansel Adams".</td>', 'This picture just has very little visual interest. It doesn''t make me think "Ansel Adams".', '2009-01-22 21:01:22.000000', NULL, 1),
(5212860, 758143, 83895, '<td valign="top">Wow , this is an amazing black and white.</td>', 'Wow , this is an amazing black and white.', '2009-01-22 21:10:21.000000', NULL, 1),
(5212900, 757096, 74821, '<td valign="top">&amp;#8800;</td>', '&#8800;', '2009-01-22 21:19:49.000000', NULL, 1),
(5212920, 756797, 101968, '<td valign="top">I like the idea very much. I love photographing the mission and I''m especially glad that the scaffolding is off of the front for now. This image seems much too processed for my taste, though.</td>', 'I like the idea very much. I love photographing the mission and I''m especially glad that the scaffolding is off of the front for now. This image seems much too processed for my taste, though.', '2009-01-22 21:33:11.000000', NULL, 1),
(5212924, 758272, 101968, '<td valign="top">The clouds are nice, but the composition is a bit flat. The image is overly processed, the area in the top right corner is especially noticeable.</td>', 'The clouds are nice, but the composition is a bit flat. The image is overly processed, the area in the top right corner is especially noticeable.', '2009-01-22 21:35:10.000000', NULL, 1),
(5212943, 758182, 101968, '<td valign="top">The composition is marvelous. The focus on the cliffs is a touch soft, and there seems to be some muck on the lens or sensor, but otherwise very good.</td>', 'The composition is marvelous. The focus on the cliffs is a touch soft, and there seems to be some muck on the lens or sensor, but otherwise very good.', '2009-01-22 21:42:30.000000', NULL, 1),
(5212960, 757556, 101968, '<td valign="top">I''m just not really feeling this picture.</td>', 'I''m just not really feeling this picture.', '2009-01-22 21:49:26.000000', NULL, 1),
(5213239, 758137, 36371, '<td valign="top">Looks like the place in the movie "Paper Moon" Love this. 10</td>', 'Looks like the place in the movie "Paper Moon" Love this. 10', '2009-01-22 23:09:22.000000', NULL, 1),
(5213240, 756849, 36371, '<td valign="top">I love the light and that wispy cloud. Beautiful! 10</td>', 'I love the light and that wispy cloud. Beautiful! 10', '2009-01-22 23:09:54.000000', NULL, 1),
(5213841, 757334, 102505, '<td valign="top">Smoothe, stong, vibrant, outstanding shot!<br/>The soft shift in tonal ranges as your eyes move into the flower is just too pleasing.<br/>perfectly framed. <br/>*bows*</td>', 'Smoothe, stong, vibrant, outstanding shot!The soft shift in tonal ranges as your eyes move into the flower is just too pleasing.perfectly framed. *bows*', '2009-01-23 03:32:30.000000', NULL, 1),
(5213842, 757516, 102505, '<td valign="top">the brown sir. you may have it! :)</td>', 'the brown sir. you may have it! :)', '2009-01-23 03:33:33.000000', NULL, 1),
(5213850, 758095, 102505, '<td valign="top">wow....simply...wow<br/>Cant help but wish I knew the fences story and the stories it could tell. How many sun sets and rises over that INCREDIBLE landscape out before it. A tease just out of my view that keeps me looking for more.<br/>I like the choice in framing and the tonal range.<br/>I would have tried to keep it a little softer...maybe impossible without losing detail in the valley below?<br/>!Magnifico!</td>', 'wow....simply...wowCant help but wish I knew the fences story and the stories it could tell. How many sun sets and rises over that INCREDIBLE landscape out before it. A tease just out of my view that keeps me looking for more.I like the choice in framing and the tonal range.I would have tried to keep it a little softer...maybe impossible without losing detail in the valley below?!Magnifico!', '2009-01-23 03:39:02.000000', NULL, 1),
(5213906, 758301, 24486, '<td valign="top">Nice lines &amp; texture.</td>', 'Nice lines & texture.', '2009-01-23 04:25:17.000000', NULL, 1),
(5214076, 756096, 88808, '<td valign="top">Love it</td>', 'Love it', '2009-01-23 07:56:24.000000', NULL, 1),
(5214079, 757453, 88808, '<td valign="top">Wow - breathtaking</td>', 'Wow - breathtaking', '2009-01-23 07:58:27.000000', NULL, 1),
(5214081, 757912, 88808, '<td valign="top">Lovely - beautiful clear still water and a wonderful reflection</td>', 'Lovely - beautiful clear still water and a wonderful reflection', '2009-01-23 07:59:33.000000', NULL, 1),
(5214091, 757421, 88808, '<td valign="top">Very atmospheric - I like it</td>', 'Very atmospheric - I like it', '2009-01-23 08:06:43.000000', NULL, 1),
(5214092, 756850, 88808, '<td valign="top">Really lovely shot</td>', 'Really lovely shot', '2009-01-23 08:07:31.000000', NULL, 1),
(5214094, 757501, 88808, '<td valign="top">The birds make this one for me - and I like the border.</td>', 'The birds make this one for me - and I like the border.', '2009-01-23 08:08:57.000000', NULL, 1),
(5214101, 756832, 88808, '<td valign="top">Love it - 9</td>', 'Love it - 9', '2009-01-23 08:12:57.000000', NULL, 1),
(5214106, 757369, 88808, '<td valign="top">Could have been sharper, and I think it would have helped if the whole flowerhead was included. Love the water drops though.</td>', 'Could have been sharper, and I think it would have helped if the whole flowerhead was included. Love the water drops though.', '2009-01-23 08:14:35.000000', NULL, 1),
(5214108, 757972, 88808, '<td valign="top">I really like this - you can feel the spray!</td>', 'I really like this - you can feel the spray!', '2009-01-23 08:15:11.000000', NULL, 1),
(5214247, 757931, 101767, '<td valign="top">The darks are very dark, but great frame, simple and effective.</td>', 'The darks are very dark, but great frame, simple and effective.', '2009-01-23 09:43:09.000000', NULL, 1),
(5214249, 757501, 101767, '<td valign="top">I like the contrasting focal points, maybe the lone tree could be offset slightly in the crop.</td>', 'I like the contrasting focal points, maybe the lone tree could be offset slightly in the crop.', '2009-01-23 09:44:48.000000', NULL, 1),
(5214253, 758093, 101767, '<td valign="top">The editing of light and dark captures the mood of the sky, i like it.</td>', 'The editing of light and dark captures the mood of the sky, i like it.', '2009-01-23 09:46:30.000000', NULL, 1),
(5214255, 756527, 101767, '<td valign="top">Nice frame.</td>', 'Nice frame.', '2009-01-23 09:48:18.000000', NULL, 1),
(5214257, 757315, 101767, '<td valign="top">Shame about the vapour trail in the sky, could have been cloned out.</td>', 'Shame about the vapour trail in the sky, could have been cloned out.', '2009-01-23 09:49:46.000000', NULL, 1),
(5214262, 757549, 101767, '<td valign="top">I like the solitude of this image.</td>', 'I like the solitude of this image.', '2009-01-23 09:51:04.000000', NULL, 1),
(5214267, 757841, 101767, '<td valign="top">Could have toned down the reflection of the sun, very atmospheric though, I like it.</td>', 'Could have toned down the reflection of the sun, very atmospheric though, I like it.', '2009-01-23 09:52:40.000000', NULL, 1),
(5214289, 757782, 102088, '<td valign="top">This is my favourite in a competition of high quality. This has Adams written all over it - just brilliant and gets my top mark</td>', 'This is my favourite in a competition of high quality. This has Adams written all over it - just brilliant and gets my top mark', '2009-01-23 10:14:19.000000', NULL, 1),
(5214291, 757044, 86232, '<td valign="top">I like this picture.</td>', 'I like this picture.', '2009-01-23 10:15:22.000000', NULL, 1),
(5214300, 758198, 101838, '<td valign="top">Nice place to capture, but the picture needs some serious cropping to become better, IMHO.<br/>I would cut sky at least in half (it''s not the best looking sky with white foam clouds to devote too much space to it) and cropped out the left 1/4 (with those distracting poles and fences).</td>', 'Nice place to capture, but the picture needs some serious cropping to become better, IMHO.I would cut sky at least in half (it''s not the best looking sky with white foam clouds to devote too much space to it) and cropped out the left 1/4 (with those distracting poles and fences).', '2009-01-23 10:19:22.000000', NULL, 1),
(5214350, 757852, 15204, '<td valign="top">I am not sure if this is highly Ansel Adams like, but I love it so I am giving it a 7.</td>', 'I am not sure if this is highly Ansel Adams like, but I love it so I am giving it a 7.', '2009-01-23 10:55:52.000000', NULL, 1),
(5214563, 757044, 97893, '<td valign="top">Very different and new composition! Well done!</td>', 'Very different and new composition! Well done!', '2009-01-23 13:02:29.000000', NULL, 1),
(5214688, 757044, 99263, '<td valign="top">I think this is a really good shot and represents the use of the zone system as used by AA very well. The image has good composition and the structure is very interesting also.</td>', 'I think this is a really good shot and represents the use of the zone system as used by AA very well. The image has good composition and the structure is very interesting also.', '2009-01-23 14:48:00.000000', NULL, 1),
(5214690, 757745, 99263, '<td valign="top">Excellent contrast and range of tones. Striking image too.</td>', 'Excellent contrast and range of tones. Striking image too.', '2009-01-23 14:48:40.000000', NULL, 1),
(5215143, 757117, 4494, '<td valign="top">Your whites are a little washed out on the back of the white goat, and on the legs and head.</td>', 'Your whites are a little washed out on the back of the white goat, and on the legs and head.', '2009-01-23 18:39:17.000000', NULL, 1),
(5215146, 758037, 4494, '<td valign="top">Pretty interesting.</td>', 'Pretty interesting.', '2009-01-23 18:39:59.000000', NULL, 1),
(5215147, 758303, 4494, '<td valign="top">The "filter" or whatever you used isn''t working here.</td>', 'The "filter" or whatever you used isn''t working here.', '2009-01-23 18:40:34.000000', NULL, 1),
