(5220944, 757578, 98171, '<td valign="top">This picture would look better if there weren''t so many branches obstructing the hut. I know you couldn''t really control that, just saying. Your title really <i>makes</i> the picture for me; it adds a story behind the photo. Wish you had bumped up the contrast more as well.</td>', 'This picture would look better if there weren''t so many branches obstructing the hut. I know you couldn''t really control that, just saying. Your title really makes the picture for me; it adds a story behind the photo. Wish you had bumped up the contrast more as well.', '2009-01-26 19:51:26.000000', NULL, 1),
(5220968, 756096, 101492, '<td valign="top">I am absolutely mesmerized.  I cannot stop looking at this one.  My hands down favorite of the competition.  I will add it to my favorites after the contest is over.  Wow!</td>', 'I am absolutely mesmerized.  I cannot stop looking at this one.  My hands down favorite of the competition.  I will add it to my favorites after the contest is over.  Wow!', '2009-01-26 20:01:25.000000', NULL, 1),
