(5223063, 757773, 32011, '<td valign="top">Congratulations on a new PB and taking out our H2H.</td>', 'Congratulations on a new PB and taking out our H2H.', '2009-01-28 00:19:16.000000', NULL, 0),
(5223065, 757968, 3037, '<td valign="top">Excellent photo Jason. Love it.</td>', 'Excellent photo Jason. Love it.', '2009-01-28 00:19:46.000000', NULL, 0),
(5223070, 757773, 67697, '<td valign="top">Beautiful!  This is such a great perspective.  It''s interesting to compare the relative size of the grass in the foreground to the obviously much bigger cascade of mountains in the background.  I feel like I can reach out and grab some snow too.  Congrats on a great finish and your new PB!</td>', 'Beautiful!  This is such a great perspective.  It''s interesting to compare the relative size of the grass in the foreground to the obviously much bigger cascade of mountains in the background.  I feel like I can reach out and grab some snow too.  Congrats on a great finish and your new PB!', '2009-01-28 00:21:29.000000', NULL, 0),
(5223079, 758347, 22301, '<td valign="top">Congrats on back to back person best! This has such great clarity and I like the dark sky.</td>', 'Congrats on back to back person best! This has such great clarity and I like the dark sky.', '2009-01-28 00:23:18.000000', NULL, 0),
(5223090, 757931, 22301, '<td valign="top">Congratulations on your first Ribbon! California went 1 and 2. :)</td>', 'Congratulations on your first Ribbon! California went 1 and 2. :)', '2009-01-28 00:25:53.000000', NULL, 0),
(5223102, 757676, 22301, '<td valign="top">I have been in that exact spot, what people who have never been don''t realize is that if you were to walk through that arch you would fall 2000 feet straight down! You pulled alot of range out of those three images. Congrats on the yellow.</td>', 'I have been in that exact spot, what people who have never been don''t realize is that if you were to walk through that arch you would fall 2000 feet straight down! You pulled alot of range out of those three images. Congrats on the yellow.', '2009-01-28 00:28:20.000000', NULL, 0),
(5223109, 756849, 22301, '<td valign="top">This really has the feel of Ansel''s work, Congrats on 4th place.</td>', 'This really has the feel of Ansel''s work, Congrats on 4th place.', '2009-01-28 00:29:14.000000', NULL, 0),
(5223114, 757676, 39349, '<td valign="top">Congrats Becky!!! Beautifully done.</td>', 'Congrats Becky!!! Beautifully done.', '2009-01-28 00:30:54.000000', NULL, 0),
(5223116, 757211, 30608, '<td valign="top">Congratulations on your well deserved "Blue"!!  Very nice!!!</td>', 'Congratulations on your well deserved "Blue"!!  Very nice!!!', '2009-01-28 00:31:08.000000', NULL, 0),
(5223126, 757968, 69668, '<td valign="top">Beautiful image Jason.  I am going skiing there next weekend.  Congrats on top 10.</td>', 'Beautiful image Jason.  I am going skiing there next weekend.  Congrats on top 10.', '2009-01-28 00:34:34.000000', NULL, 0),
(5223147, 757676, 30608, '<td valign="top">Congratulations Becky!! I know exactly how you felt with two 7+ scores and that didn''t ribbon. I love this image and thought this would actually take first.</td>', 'Congratulations Becky!! I know exactly how you felt with two 7+ scores and that didn''t ribbon. I love this image and thought this would actually take first.', '2009-01-28 00:38:38.000000', NULL, 0),
(5223150, 756947, 42013, '<td valign="top">Robert, I really liked this one(8) and the only thing that didn''t feel right to me was the ultra level of detail(maybe it felt too tone mapped or something) That didn''t hurt the image score wise for me but I wonder what others thought. Seeing your lack of comments, it is hard to tell. Hmmm...</td>', 'Robert, I really liked this one(8) and the only thing that didn''t feel right to me was the ultra level of detail(maybe it felt too tone mapped or something) That didn''t hurt the image score wise for me but I wonder what others thought. Seeing your lack of comments, it is hard to tell. Hmmm...', '2009-01-28 00:39:14.000000', NULL, 0),
(5223163, 756878, 69008, '<td valign="top">I see it :  )   <br/> The twists in the foreground trunks adds a ton of interest that would not otherwise be there.  It somehow fits nicely to the overall effect of the gentle curves to the left from the bottom.</td>', 'I see it :  )    The twists in the foreground trunks adds a ton of interest that would not otherwise be there.  It somehow fits nicely to the overall effect of the gentle curves to the left from the bottom.', '2009-01-28 00:42:04.000000', NULL, 0),
(5223167, 758182, 69008, '<td valign="top">I like the combination of textures in this shot.  Nice stuff.</td>', 'I like the combination of textures in this shot.  Nice stuff.', '2009-01-28 00:43:23.000000', NULL, 0),
(5223174, 757441, 39427, '<td valign="top">oh WHAT?  Underrated... I gave you an 8, this deserves at least top 10 I don''t know what people are thinking... would have been a complete dynamite shot with some clouds up there</td>', 'oh WHAT?  Underrated... I gave you an 8, this deserves at least top 10 I don''t know what people are thinking... would have been a complete dynamite shot with some clouds up there', '2009-01-28 00:44:36.000000', NULL, 0),
(5223183, 757144, 69008, '<td valign="top">Nice place!  I feel that the pan crop may have hurt this one in the voting.</td>', 'Nice place!  I feel that the pan crop may have hurt this one in the voting.', '2009-01-28 00:45:38.000000', NULL, 0),
(5223191, 757676, 61552, '<td valign="top">Good Job Becky!  I expected it to ribbon!</td>', 'Good Job Becky!  I expected it to ribbon!', '2009-01-28 00:47:10.000000', NULL, 0),
(5223193, 758152, 40718, '<td valign="top">Ugh! The dreaded 11th.  It''s a great shot though!</td>', 'Ugh! The dreaded 11th.  It''s a great shot though!', '2009-01-28 00:47:32.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5223202, 757211, 31637, '<td valign="top">Keep on winnin em man, landscape master you are, and this is why!, tonal range is very good, congrats!</td>', 'Keep on winnin em man, landscape master you are, and this is why!, tonal range is very good, congrats!', '2009-01-28 00:50:22.000000', NULL, 0),
(5223207, 758154, 76430, '<td valign="top">Bummer about the lack of comments.  This does not have an AA look to it.  The ground takes too little of the frame and does not really have much of interest in it.  The bright sun overpowers this shot, and I don''t know if that''s a sun dog on the right, but it looks like lots of lens flare.  I think if you had taken it at sunrise/sunset it would have been better, but of course then you wouldn''t have the sun dog, and according to the title that was the main reason for the shot.<br/>[eta] Looking at where you live (Winnipeg) I see why it looks like where I was born and raised.  You''re about 100 miles from my home.<br/><br/><i>Message edited by author 2009-01-28 00:53:24.</i></td>', 'Bummer about the lack of comments.  This does not have an AA look to it.  The ground takes too little of the frame and does not really have much of interest in it.  The bright sun overpowers this shot, and I don''t know if that''s a sun dog on the right, but it looks like lots of lens flare.  I think if you had taken it at sunrise/sunset it would have been better, but of course then you wouldn''t have the sun dog, and according to the title that was the main reason for the shot.[eta] Looking at where you live (Winnipeg) I see why it looks like where I was born and raised.  You''re about 100 miles from my home.', '2009-01-28 00:51:08.000000', '2009-01-28 00:53:24.000000', 0),
(5223209, 757676, 31637, '<td valign="top">Great tonal range, nice composition, and a great 3rd place finish in a challenge with so many great shots.</td>', 'Great tonal range, nice composition, and a great 3rd place finish in a challenge with so many great shots.', '2009-01-28 00:51:40.000000', NULL, 0),
(5223212, 758143, 31637, '<td valign="top">This one is very nice! could have easily won, but 5 out of 219 makes it a winner without a doubt!</td>', 'This one is very nice! could have easily won, but 5 out of 219 makes it a winner without a doubt!', '2009-01-28 00:52:43.000000', NULL, 0),
(5223222, 757447, 69008, '<td valign="top">A little processing to bring up the detail in the trees would have improved the effect of this shot.  It may be my monitor, but the mid-sections of the trees is near totally dark. I can make out the limbs but I have to work to see them. Maybe a different time of day would have made the difference, but then the mist may have shrouded the mountain.</td>', 'A little processing to bring up the detail in the trees would have improved the effect of this shot.  It may be my monitor, but the mid-sections of the trees is near totally dark. I can make out the limbs but I have to work to see them. Maybe a different time of day would have made the difference, but then the mist may have shrouded the mountain.', '2009-01-28 00:55:35.000000', NULL, 0),
(5223229, 758051, 76430, '<td valign="top">I have to give you one comment at least.  This picture has potential, but IMHO there is too much level ground in the front and the building doesn''t have enough definition.  I think if you got closer to the building it would be better.  Also if you increased the contrast it would make it more interesting and more like an AA picture.</td>', 'I have to give you one comment at least.  This picture has potential, but IMHO there is too much level ground in the front and the building doesn''t have enough definition.  I think if you got closer to the building it would be better.  Also if you increased the contrast it would make it more interesting and more like an AA picture.', '2009-01-28 00:58:31.000000', NULL, 0),
(5223233, 757211, 39429, '<td valign="top">Beautiful.  Congratulations on one of my favorites of the challenge.</td>', 'Beautiful.  Congratulations on one of my favorites of the challenge.', '2009-01-28 00:59:39.000000', NULL, 0),
(5223242, 757931, 39429, '<td valign="top">Beautiful.  This image is one that really caught my eye.  Congratulations.</td>', 'Beautiful.  This image is one that really caught my eye.  Congratulations.', '2009-01-28 01:00:39.000000', NULL, 0),
(5223244, 756947, 51638, '<td valign="top">I was interested to see which entry was yours Robert, considering you knew AA and thus his style so well. On the one hand I''m surprised this didn''t score higher as I think the lighting, PP etc are spot on. On the other hand it''s not the expansive canyons/mountains scene that I think some voters needed for them to vote high. IMO it''s a great image tho.</td>', 'I was interested to see which entry was yours Robert, considering you knew AA and thus his style so well. On the one hand I''m surprised this didn''t score higher as I think the lighting, PP etc are spot on. On the other hand it''s not the expansive canyons/mountains scene that I think some voters needed for them to vote high. IMO it''s a great image tho.', '2009-01-28 01:00:53.000000', NULL, 0),
(5223247, 756547, 69008, '<td valign="top">Hi Sue! This is very pretty, and I like the simplicity of it.  <br/>As an Adams landscape, I am not seeing the great amount detail that he included in almost all of his landscapes. The wide expanse of lake looks nice in this shot, but just not "Adams-ish" to me. I think that may be the reason some people voted this low.  <br/>As always with your shot, great sky.</td>', 'Hi Sue! This is very pretty, and I like the simplicity of it.  As an Adams landscape, I am not seeing the great amount detail that he included in almost all of his landscapes. The wide expanse of lake looks nice in this shot, but just not "Adams-ish" to me. I think that may be the reason some people voted this low.  As always with your shot, great sky.', '2009-01-28 01:01:53.000000', NULL, 0),
(5223254, 756849, 39429, '<td valign="top">Very beautiful.  I''m very impressed.  Congratulations.</td>', 'Very beautiful.  I''m very impressed.  Congratulations.', '2009-01-28 01:06:50.000000', NULL, 0),
(5223262, 758143, 39429, '<td valign="top">Congratulations on an Honorable Mention and a personal best.  Beautiful shot.</td>', 'Congratulations on an Honorable Mention and a personal best.  Beautiful shot.', '2009-01-28 01:08:23.000000', NULL, 0),
