(5223456, 757537, 51027, '<td valign="top">Woo hoo! Beauty.</td>', 'Woo hoo! Beauty.', '2009-01-28 02:59:56.000000', NULL, 0),
(5223462, 757931, 16230, '<td valign="top">You gotta love that reflection. Congrats on the ribbon a great photo David!</td>', 'You gotta love that reflection. Congrats on the ribbon a great photo David!', '2009-01-28 03:03:02.000000', NULL, 0),
(5223476, 758196, 66097, '<td valign="top">Such a pitty so many voters gave you 1''s and 2''s etc, I wonder if more out of lack of knowledge with all of AA''S work. You took a chance on an obscure image of his and produced an image with clarity, more than I can say about some that landed in the 6''s. Bravo to you. This IMO should have scored higher.</td>', 'Such a pitty so many voters gave you 1''s and 2''s etc, I wonder if more out of lack of knowledge with all of AA''S work. You took a chance on an obscure image of his and produced an image with clarity, more than I can say about some that landed in the 6''s. Bravo to you. This IMO should have scored higher.', '2009-01-28 03:16:43.000000', NULL, 0),
(5223487, 757211, 88523, '<td valign="top">Right on Joe!!!</td>', 'Right on Joe!!!', '2009-01-28 03:33:59.000000', NULL, 0),
