(5882992, 757585, 60899, '<td valign="top">Very Nice ... love the contrast in the image<br/></td>', 'Very Nice ... love the contrast in the image', '2010-02-27 23:36:41.000000', NULL, 0),
(6123880, 758347, 40718, '<td valign="top">The sky and upper mountain are classic contrasty material.  I think your little tree mound lets you down a bit by being in strong shadow.  The trees become mushy and the contrast is pretty light.  Still, I''m not sure you would be safe if it were in sunlight because it might get lost in the mountain behind.  Sometimes you just do the best with what you got. :)</td>', 'The sky and upper mountain are classic contrasty material.  I think your little tree mound lets you down a bit by being in strong shadow.  The trees become mushy and the contrast is pretty light.  Still, I''m not sure you would be safe if it were in sunlight because it might get lost in the mountain behind.  Sometimes you just do the best with what you got. :)', '2010-08-08 23:26:24.000000', NULL, 0),
(6456416, 756458, 40391, '<td valign="top">I''ve only got my mobile at the moment so I will come back to this amazing image later. But even on the small screen you can tell that this shot is great! And those clouds are incredible.</td>', 'I''ve only got my mobile at the moment so I will come back to this amazing image later. But even on the small screen you can tell that this shot is great! And those clouds are incredible.', '2011-06-30 04:05:04.000000', NULL, 0),
